sp_widget.client_script:
api.controller = function(spModal, $window, $interval) {

    var c = this;

    c.idProofFile = null;
    c.idProofFileName = "";


    c.organizerSysId = "";

    c.isSubmitting = false;
    c.isCreatingAccount = false;

    c.verificationStatus = "not_submitted";

    c.organizerPassword = "";
    c.confirmOrganizerPassword = "";
	c.contactNumber = "";

    var statusTimer = null;

    c.idProofSelected = function(input) {

        if (!input.files || input.files.length === 0) {
            c.idProofFile = null;
            c.idProofFileName = "";
            return;
        }

        var file = input.files[0];

        var maxSize = 5 * 1024 * 1024;

        if (file.size > maxSize) {
            spModal.alert(
                "ID Proof must be smaller than 5 MB."
            );

            input.value = "";
            return;
        }

        var allowedTypes = [
            "image/jpeg",
            "image/png",
            "application/pdf"
        ];

        if (allowedTypes.indexOf(file.type) === -1) {
            spModal.alert(
                "Please upload JPG, JPEG, PNG or PDF."
            );

            input.value = "";
            return;
        }

        var reader = new FileReader();

        reader.onload = function(event) {

            c.idProofFile = {
                name: file.name,
                type: file.type,
                data: event.target.result.split(",")[1]
            };

            c.idProofFileName = file.name;

            angular.element(input)
                .scope()
                .$apply();
        };

        reader.readAsDataURL(file);
    };




    c.verifyOrganizer = function() {

        if (c.isSubmitting)
            return;


        if (
    !c.organizerName ||
    !c.email ||
    !c.college ||
    !c.contactNumber
) {

            spModal.alert(
                "Please fill in all required organizer information."
            );

            return;
        }


        if (!c.idProofFile) {

            spModal.alert(
                "Please upload your ID Proof."
            );

            return;
        }





        c.isSubmitting = true;


        c.server.get({

            action: "verify_organizer",

            organizerName:
                c.organizerName,

            email:
                c.email,

            college:
                c.college,
			contactNumber:
                c.contactNumber,	

            idProofFileName:
                c.idProofFile.name,

            idProofFileType:
                c.idProofFile.type,

            idProofFileData:
                c.idProofFile.data,



        }).then(function(response) {

            c.isSubmitting = false;

            var result =
                response.data;


            if (result.success) {

                c.organizerSysId =
                    result.organizerSysId;

                c.verificationStatus =
                    "pending";


                spModal.alert(
                    "Organizer verification request submitted successfully.\n\n" +
                    "Please wait for administrator approval."
                );


                c.startApprovalCheck();

            } else {

                spModal.alert(
                    result.message ||
                    "Unable to submit organizer verification."
                );
            }

        }, function() {

            c.isSubmitting = false;

            spModal.alert(
                "Something went wrong while submitting the verification request."
            );
        });
    };


    c.checkApprovalStatus = function() {

        if (!c.organizerSysId)
            return;


        c.server.get({

            action: "check_status",

            organizerSysId:
                c.organizerSysId

        }).then(function(response) {

            var result =
                response.data;


            if (result.status === "verified") {

                c.verificationStatus =
                    "verified";

                c.stopApprovalCheck();

                spModal.alert(
                    "Your organizer verification has been approved."
                );
            }


            if (
                result.status === "not-verified" ||
                result.status === "rejected"
            ) {

                c.verificationStatus =
                    "not-verified";

                c.stopApprovalCheck();

                spModal.alert(
                    "Your organizer verification was not approved."
                );
            }

        });
    };


    c.startApprovalCheck = function() {

        c.stopApprovalCheck();

        statusTimer =
            $interval(function() {

                c.checkApprovalStatus();

            }, 5000);
    };


    c.stopApprovalCheck = function() {

        if (statusTimer) {

            $interval.cancel(statusTimer);

            statusTimer = null;
        }
    };


    c.createAccount = function() {

        if (
            c.verificationStatus !==
            "verified"
        ) {

            spModal.alert(
                "Your organizer verification must be approved first."
            );

            return;
        }


        if (c.isCreatingAccount)
            return;


        if (
            !c.organizerPassword ||
            !c.confirmOrganizerPassword
        ) {

            spModal.alert(
                "Please enter and confirm your password."
            );

            return;
        }


        if (
            c.organizerPassword !==
            c.confirmOrganizerPassword
        ) {

            spModal.alert(
                "Password and Confirm Password do not match."
            );

            return;
        }


        if (
            c.organizerPassword.length < 8
        ) {

            spModal.alert(
                "Password must contain at least 8 characters."
            );

            return;
        }


        c.isCreatingAccount = true;


        c.server.get({

            action:
                "create_account",

            organizerSysId:
                c.organizerSysId,

            password:
                c.organizerPassword

        }).then(function(response) {

            c.isCreatingAccount = false;

            var result =
                response.data;


            if (result.success) {

                spModal.alert(
                    "Organizer Account created successfully."
                ).then(function() {

                    $window.location.href =
                        "?id=campus_organizer_login";

                });

            } else {

                spModal.alert(
                    result.message ||
                    "Unable to create Organizer Account."
                );
            }

        }, function() {

            c.isCreatingAccount = false;

            spModal.alert(
                "Something went wrong while creating the Organizer Account."
            );
        });
    };


    c.$onDestroy = function() {

        c.stopApprovalCheck();

    };

};

sp_widget.css:
.organizer-signup-page {

    min-height: 100vh;

    padding: 40px 16px;

    background:
        linear-gradient(
            135deg,
            #eff6ff,
            #ffffff
        );

    display: flex;

    align-items: center;

    justify-content: center;

    box-sizing: border-box;

    font-family: Arial, sans-serif;
}


.signup-card {

    width: 100%;

    max-width: 620px;

    padding: 36px;

    background: #ffffff;

    border: 1px solid #dbeafe;

    border-radius: 16px;

    box-shadow:
        0 12px 35px
        rgba(15, 61, 145, 0.10);

    box-sizing: border-box;
}


.signup-icon {

    width: 64px;

    height: 64px;

    margin: 0 auto 18px;

    display: flex;

    align-items: center;

    justify-content: center;

    color: #2563eb;

    background: #eff6ff;

    border-radius: 50%;

    font-size: 30px;
}


.signup-card h1 {

    margin: 0 0 10px;

    color: #0f3d91;

    text-align: center;

    font-size: 28px;

    font-weight: 700;
}


.signup-subtitle {

    margin: 0 0 28px;

    color: #64748b;

    text-align: center;

    line-height: 1.6;

}


.form-group {

    margin-bottom: 20px;
}


.form-group label {

    display: block;

    margin-bottom: 8px;

    color: #1e293b;

    font-weight: 600;
}


.required {

    color: #dc2626;
}


.form-control {

    width: 100%;

    min-height: 46px;

    padding: 11px 13px;

    color: #0f172a;

    background: #ffffff;

    border: 1px solid #cbd5e1;

    border-radius: 8px;

    font-size: 14px;

    box-sizing: border-box;

    transition:
        border-color .2s,
        box-shadow .2s;
}


.form-control:focus {

    border-color: #2563eb;

    outline: none;

    box-shadow:
        0 0 0 3px
        rgba(37, 99, 235, .12);
}


.form-group input[type="file"] {

    padding: 10px;

    background: #f8fafc;
}


.file-help {

    display: block;

    margin-top: 7px;

    color: #64748b;

    line-height: 1.5;

    font-size: 12px;
}


.file-selected {

    margin-top: 10px;

    padding: 10px 12px;

    overflow-wrap: anywhere;

    color: #1d4ed8;

    background: #eff6ff;

    border-radius: 7px;

    font-size: 13px;
}


/* Verification Status */

.status-box {

    margin: 22px 0;

    padding: 14px;

    display: flex;

    flex-wrap: wrap;

    gap: 8px;

    align-items: center;

    background: #f8fafc;

    border: 1px solid #e2e8f0;

    border-radius: 8px;

    color: #334155;
}


.status-not-submitted {

    color: #64748b;

    font-weight: 600;
}


.status-pending {

    color: #92400e;

    font-weight: 700;
}


.status-approved {

    color: #15803d;

    font-weight: 700;
}


.status-rejected {

    color: #b91c1c;

    font-weight: 700;
}


/* Verify Button */

.verify-submit {

    width: 100%;

    min-height: 48px;

    padding: 12px 18px;

    margin-bottom: 16px;

    border: none;

    border-radius: 8px;

    color: #ffffff;

    background: #2563eb;

    font-size: 15px;

    font-weight: 600;

    cursor: pointer;

    transition:
        background .2s,
        transform .2s;
}


.verify-submit:hover:not(:disabled) {

    background: #1d4ed8;

    transform: translateY(-1px);
}


/* Password Section */

.password-section {

    margin-top: 20px;

    padding: 22px;

    background: #f8fbff;

    border: 1px solid #bfdbfe;

    border-radius: 10px;
}


.approved-heading {

    margin-bottom: 22px;

    color: #15803d;

    font-size: 16px;

    font-weight: 700;

    text-align: center;
}


/* Create Account */

.signup-submit {

    width: 100%;

    min-height: 48px;

    padding: 12px 18px;

    border: none;

    border-radius: 8px;

    color: #ffffff;

    background: #0f3d91;

    font-size: 15px;

    font-weight: 600;

    cursor: pointer;

    transition:
        background .2s,
        transform .2s;
}


.signup-submit:hover:not(:disabled) {

    background: #0b2f73;

    transform: translateY(-1px);
}


.verify-submit:disabled,
.signup-submit:disabled {

    opacity: .55;

    cursor: not-allowed;
}


/* Verification Messages */

.verification-message {

    margin-top: 18px;

    padding: 13px;

    color: #92400e;

    background: #fffbeb;

    border: 1px solid #fde68a;

    border-radius: 8px;

    font-size: 13px;

    line-height: 1.6;
}


.verification-message.approved {

    color: #166534;

    background: #f0fdf4;

    border-color: #bbf7d0;
}


.verification-message.rejected {

    color: #991b1b;

    background: #fef2f2;

    border-color: #fecaca;
}


/* Footer */

.signup-footer {

    margin-top: 26px;

    padding-top: 20px;

    border-top: 1px solid #e2e8f0;

    display: flex;

    flex-wrap: wrap;

    justify-content: center;

    gap: 6px;

    color: #64748b;

    font-size: 14px;
}


.signup-footer a {

    color: #2563eb;

    font-weight: 600;

    text-decoration: none;
}


.signup-footer a:hover {

    text-decoration: underline;
}


/* Mobile */

@media (max-width: 700px) {

    .organizer-signup-page {

        padding: 24px 12px;

    }

    .signup-card {

        padding: 26px 22px;

    }

    .signup-card h1 {

        font-size: 25px;

    }

}


@media (max-width: 450px) {

    .signup-card {

        padding: 22px 16px;

    }

    .signup-card h1 {

        font-size: 23px;

    }

    .status-box {

        align-items: flex-start;

        flex-direction: column;

    }

}

sp_widget.script:
(function() {

    data.success = false;
    data.message = "";
    data.organizerSysId = "";
    data.userSysId = "";
    data.status = "";
    data.accountCreated = false;

    if (!input) {
        return;
    }


    /* =====================================================
       ORGANIZER VERIFICATION SUBMISSION
       ===================================================== */

    if (input.action === "verify_organizer") {

        var organizerName =
            (input.organizerName || "").trim();

        var email =
            (input.email || "").trim();

        var college =
            (input.college || "").trim();

        var contactNumber =
            (input.contactNumber || "").trim();

        var idProofFileName =
            (input.idProofFileName || "").trim();

        var idProofFileType =
            (input.idProofFileType || "").trim();

        var idProofFileData =
            input.idProofFileData || "";


        /* Required organizer information */

        if (
            !organizerName ||
            !email ||
            !college ||
            !contactNumber
        ) {

            data.message =
                "Please provide all required organizer information.";

            return;
        }


        /* ID Proof is required */

        if (
            !idProofFileName ||
            !idProofFileType ||
            !idProofFileData
        ) {

            data.message =
                "Please upload your ID Proof.";

            return;
        }


        /* =====================================================
           CHECK EXISTING ORGANIZER
           ===================================================== */

        var existingOrganizer =
            new GlideRecord(
                "x_snc_campus_con_0_event_organizers"
            );

        existingOrganizer.addQuery(
            "contact_email",
            email
        );

        existingOrganizer.setLimit(1);

        existingOrganizer.query();


        if (existingOrganizer.next()) {

            data.message =
                "An Organizer Profile already exists for this email.";

            return;
        }


        /* =====================================================
           CHECK EXISTING SERVICE NOW USER
           ===================================================== */

        var existingUser =
            new GlideRecord("sys_user");

        existingUser.addQuery(
            "email",
            email
        );

        existingUser.setLimit(1);

        existingUser.query();


        if (existingUser.next()) {

            data.message =
                "An account already exists for this email.";

            return;
        }


        /* =====================================================
           CREATE INACTIVE SERVICE NOW USER
           ===================================================== */

        var user =
            new GlideRecord("sys_user");

        user.initialize();

        user.setValue(
            "user_name",
            email
        );

        user.setValue(
            "email",
            email
        );

        user.setValue(
            "first_name",
            organizerName
        );

        user.setValue(
            "active",
            false
        );

        user.setValue(
            "password_needs_reset",
            true
        );


        var userSysId =
            user.insert();


        if (!userSysId) {

            data.message =
                "Unable to create Organizer Account.";

            return;
        }


        /* =====================================================
           CREATE EVENT ORGANIZER PROFILE
           ===================================================== */

        var organizer =
            new GlideRecord(
                "x_snc_campus_con_0_event_organizers"
            );

        organizer.initialize();


        /*
         * Organizer Name is a reference
         * to the sys_user table.
         */

        organizer.setValue(
            "organizer_name",
            userSysId
        );

        organizer.setValue(
            "college_institution",
            college
        );

        organizer.setValue(
            "contact_email",
            email
        );

        organizer.setValue(
            "contact_number",
            contactNumber
        );

        organizer.setValue(
            "verification_status",
            "pending"
        );


        var organizerSysId =
            organizer.insert();


        if (!organizerSysId) {

            user.deleteRecord();

            data.message =
                "Unable to create Organizer Profile.";

            return;
        }


        /* =====================================================
           UPLOAD ID PROOF
           ===================================================== */

        var attachment =
            new GlideSysAttachment();


        var idProofAttachmentSysId =
            attachment.writeBase64(
                organizer,
                idProofFileName,
                idProofFileType,
                idProofFileData
            );


        if (!idProofAttachmentSysId) {

            organizer.deleteRecord();

            user.deleteRecord();

            data.message =
                "Organizer Profile was created, but ID Proof upload failed.";

            return;
        }


        /* Store attachment in ID Proof Upload field */

        organizer.setValue(
            "id_proof_upload",
            idProofAttachmentSysId
        );


        organizer.update();


        /* =====================================================
           SUCCESS
           ===================================================== */

        data.success = true;

        data.organizerSysId =
            organizerSysId;

        data.userSysId =
            userSysId;

        data.status =
            "pending";

        data.message =
            "Organizer verification request submitted successfully.";

        return;
    }


    /* =====================================================
       CHECK ORGANIZER VERIFICATION STATUS
       ===================================================== */

    if (input.action === "check_status") {

        var organizerSysId =
            input.organizerSysId || "";


        if (!organizerSysId) {

            data.status =
                "not_found";

            return;
        }


        var organizerCheck =
            new GlideRecord(
                "x_snc_campus_con_0_event_organizers"
            );


        if (!organizerCheck.get(
            organizerSysId
        )) {

            data.status =
                "not_found";

            return;
        }


        data.status =
            String(
                organizerCheck.getValue(
                    "verification_status"
                ) || ""
            ).toLowerCase();


        return;
    }


    /* =====================================================
       CREATE ORGANIZER ACCOUNT AFTER APPROVAL
       ===================================================== */

    if (input.action === "create_account") {

        var requestedOrganizer =
            input.organizerSysId || "";

        var password =
            input.password || "";


        /* Check Organizer Profile */

        if (!requestedOrganizer) {

            data.message =
                "Organizer Profile was not found.";

            return;
        }


        /* Check password */

        if (!password) {

            data.message =
                "Please provide a password.";

            return;
        }


        /* Get Organizer Profile */

        var approvedOrganizer =
            new GlideRecord(
                "x_snc_campus_con_0_event_organizers"
            );


        if (!approvedOrganizer.get(
            requestedOrganizer
        )) {

            data.message =
                "Organizer Profile could not be found.";

            return;
        }


        /* =====================================================
           CHECK VERIFICATION STATUS
           ===================================================== */

        var verificationStatus =
            String(
                approvedOrganizer.getValue(
                    "verification_status"
                ) || ""
            ).toLowerCase();


        if (
            verificationStatus !==
            "verified"
        ) {

            data.message =
                "Your Organizer verification has not been approved.";

            return;
        }


        /* =====================================================
           GET LINKED SERVICE NOW USER
           ===================================================== */

        var linkedUserSysId =
            approvedOrganizer.getValue(
                "organizer_name"
            );


        if (!linkedUserSysId) {

            data.message =
                "Organizer User Account could not be found.";

            return;
        }


        var organizerUser =
            new GlideRecord("sys_user");


        if (!organizerUser.get(
            linkedUserSysId
        )) {

            data.message =
                "Organizer User Account could not be found.";

            return;
        }


        /* =====================================================
           SET PASSWORD CORRECTLY
           ===================================================== */

        organizerUser.user_password
            .setDisplayValue(password);


        /* Activate the account */

        organizerUser.setValue(
            "active",
            true
        );


        /*
         * The organizer has just created the password,
         * so no password reset is required.
         */

        organizerUser.setValue(
            "password_needs_reset",
            false
        );


        organizerUser.update();


        /* =====================================================
           SUCCESS
           ===================================================== */

        data.success = true;

        data.accountCreated = true;

        data.message =
            "Organizer Account created successfully.";

        return;
    }


})();
